note_models.css:
@font-face {
  font-family: "M Plus 2";
  src: url("_Mplus2-Regular.ttf");
}

html, body {
  height: 100%;
  margin: 0;
}

.card {
  font-family: "M Plus 2", system-ui, sans-serif;
  color: #fff;
  box-sizing: border-box;
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}

.katakana-front {
  font-size: clamp(1.8rem, 8vw, 3rem);
  font-weight: 700;
  white-space: nowrap;
}

.katakana-back {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 5.5rem;
  font-size: clamp(1.5rem, 5vw, 2rem);
  font-weight: 200;
  opacity: 0.7;
  margin-bottom: 0.75rem;
  white-space: nowrap;
  cursor: pointer;
  transition: opacity 0.2s;
  position: relative;
}

.katakana-back:hover {
  opacity: 1;
  color: #89b4fa;
}

.romaji-hover, .tooltip {
  visibility: hidden;
  opacity: 0;
  color: rgba(255, 255, 255, 0.6);
  white-space: nowrap;
  pointer-events: none;
  transition: opacity 0.25s cubic-bezier(0.16, 1, 0.3, 1), 
              transform 0.25s cubic-bezier(0.16, 1, 0.3, 1), 
              visibility 0.25s ease;
}

.romaji-hover {
  font-size: 0.7em;
  margin-bottom: 10px;
  transform: translateY(16px);
}

.katakana-back:hover .romaji-hover {
  visibility: visible;
  opacity: 1;
  transform: translateY(0);
}

.meaning {
  font-size: 1.85rem;
  font-weight: 550;
  cursor: pointer;
}

.origin, .notes {
  font-style: italic;
  opacity: 0.85;
}

.origin {
  font-size: 1.05rem;
  margin-bottom: 0.5rem;
}

.notes {
  font-size: 0.95rem;
  opacity: 0.7;
}

img {
  max-width: 60vw;
  max-height: 30vh;
  object-fit: contain;
  border-radius: 8px;
}

.img-src { 
  position: relative; 
  display: inline-block;
  cursor: pointer;
}

.tooltip {
  position: absolute; 
  top: 100%; 
  left: 50%; 
  margin-top: 10px;
  transform: translateY(16px) translateX(-50%);
}

.img-src:hover .tooltip, 
.img-src:active .tooltip { 
  visibility: visible;
  opacity: 1;
  transform: translateY(0) translateX(-50%);
}

.audio { display: none; }
